std::vector<f::Channel> catalog(){return {{"density","density-q","effects",f::Domain::VisualReference,f::Merge::Sum,0,1000,1000},{"moisture","wetness-q","effects",f::Domain::VisualReference,f::Merge::Maximum,0,1000,1000}};}
f::GpuLease read(f::GpuVisualWorld& world){f::LeaseRequest r;r.owner="consumer";r.channels={0};r.region={{-1,-1,-1},{7,7,7}};r.haloCells=1;r.maxPages=64;r.maxAgeTicks=1;auto a=world.acquire(r);require(a.accepted,a.error.c_str());return a.lease;}
struct Query {
    gpu_test::Com<ID3D12RootSignature> root;gpu_test::Com<ID3D12PipelineState> pipeline;
    explicit Query(Rig& rig){D3D12_ROOT_PARAMETER p[4]{};p[0].ParameterType=D3D12_ROOT_PARAMETER_TYPE_32BIT_CONSTANTS;p[0].Constants.Num32BitValues=28;p[1].ParameterType=p[2].ParameterType=D3D12_ROOT_PARAMETER_TYPE_SRV;p[2].Descriptor.ShaderRegister=1;p[3].ParameterType=D3D12_ROOT_PARAMETER_TYPE_UAV;D3D12_ROOT_SIGNATURE_DESC d{};d.NumParameters=4;d.pParameters=p;d.Flags=D3D12_ROOT_SIGNATURE_FLAG_CBV_SRV_UAV_HEAP_DIRECTLY_INDEXED;gpu_test::Com<ID3DBlob> bytes,errors;gpu_test::hr(D3D12SerializeRootSignature(&d,D3D_ROOT_SIGNATURE_VERSION_1,bytes.out(),errors.out()),"Serialize WF query root");gpu_test::hr(rig.device.p->CreateRootSignature(0,bytes.p->GetBufferPointer(),bytes.p->GetBufferSize(),IID_PPV_ARGS(root.out())),"Create WF query root");D3D12_COMPUTE_PIPELINE_STATE_DESC pd{};pd.pRootSignature=root.p;pd.CS={nativegpu::shaders::kFieldQuery.data,nativegpu::shaders::kFieldQuery.size};gpu_test::hr(rig.device.p->CreateComputePipelineState(&pd,IID_PPV_ARGS(pipeline.out())),"Create existing field query PSO");}
    std::vector<f::GpuFieldAnswer> run(Rig& rig,const std::shared_ptr<f::GpuVisualView>& view,const std::vector<f::GpuFieldQuery>& input,f::Tick tick){
        require(!!view,"Missing GPU WF view");const auto b=view->bindings();const auto inputBytes=input.size()*sizeof(f::GpuFieldQuery),bytes=input.size()*sizeof(f::GpuFieldAnswer);gpu_test::Com<ID3D12Resource> requests,output,read;
        gpu_test::makeBuffer(rig.device.p,requests,inputBytes,D3D12_HEAP_TYPE_UPLOAD,D3D12_RESOURCE_STATE_GENERIC_READ);gpu_test::makeBuffer(rig.device.p,read,bytes,D3D12_HEAP_TYPE_READBACK,D3D12_RESOURCE_STATE_COPY_DEST);void* data=nullptr;D3D12_RANGE none{0,0};gpu_test::hr(requests.p->Map(0,&none,&data),"Map WF query requests");std::memcpy(data,input.data(),inputBytes);requests.p->Unmap(0,nullptr);
        D3D12_HEAP_PROPERTIES heap{};heap.Type=D3D12_HEAP_TYPE_DEFAULT;heap.CreationNodeMask=heap.VisibleNodeMask=1;D3D12_RESOURCE_DESC desc{};desc.Dimension=D3D12_RESOURCE_DIMENSION_BUFFER;desc.Width=bytes;desc.Height=1;desc.DepthOrArraySize=desc.MipLevels=1;desc.SampleDesc.Count=1;desc.Layout=D3D12_TEXTURE_LAYOUT_ROW_MAJOR;desc.Flags=D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS;gpu_test::hr(rig.device.p->CreateCommittedResource(&heap,D3D12_HEAP_FLAG_NONE,&desc,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,nullptr,IID_PPV_ARGS(output.out())),"Create WF query output");
        rig.begin();require(view->markUsed(rig.ticket()),"WF query actual fence rejected");ID3D12DescriptorHeap* heaps[]={b.descriptors};rig.commands.p->SetDescriptorHeaps(1,heaps);rig.commands.p->SetComputeRootSignature(root.p);rig.commands.p->SetPipelineState(pipeline.p);auto constants=b.constants(input.size(),tick);rig.commands.p->SetComputeRoot32BitConstants(0,28,constants.data(),0);rig.commands.p->SetComputeRootShaderResourceView(1,b.pageTable);rig.commands.p->SetComputeRootShaderResourceView(2,requests.p->GetGPUVirtualAddress());rig.commands.p->SetComputeRootUnorderedAccessView(3,output.p->GetGPUVirtualAddress());rig.commands.p->Dispatch((input.size()+63)/64,1,1);gpu_test::transition(rig.commands.p,output.p,D3D12_RESOURCE_STATE_UNORDERED_ACCESS,D3D12_RESOURCE_STATE_COPY_SOURCE);rig.commands.p->CopyBufferRegion(read.p,0,output.p,0,bytes);rig.submit();
        D3D12_RANGE range{0,bytes};gpu_test::hr(read.p->Map(0,&range,&data),"Map completed WF validation");std::vector<f::GpuFieldAnswer> result(input.size());std::memcpy(result.data(),data,bytes);read.p->Unmap(0,&none);return result;
    }
};
// This test coordinator exercises the public runtime driver against the real
// LEF/WF services. It is not the renderer/asset lifecycle coordinator.
struct Writer {
    struct Entry {f::GpuLocalHandle local;f::GpuSharingHandle sharing;bool retiring=false,localRetired=false;};
    Rig& rig;f::GpuLocalFields local;f::GpuVisualWorld world;f::GpuFieldSharing sharing;std::map<std::uint64_t,Entry> entries;
    std::uint64_t simulated=0,flushed=0;std::vector<std::size_t> liveSets;
    explicit Writer(Rig& r):rig(r),local(r.device.p,r.fence.p,catalog()),world(r.device.p,r.fence.p,catalog()),sharing(world){}
    bool record(const e::GpuDepositFrame& frame,std::string& error){
        require(frame.commands==rig.commands.p&&frame.fence==rig.ticket(),"Deposit callback command/fence mismatch");liveSets.push_back(frame.instances.size());std::set<std::uint64_t> live;
        for(const auto& i:frame.instances){live.insert(i.serial);require(i.asset&&i.emitters.size()==i.asset->emitters.size(),"Deposit callback lost its immutable emitter contract");}
        for(auto& pair:entries)if(!live.count(pair.first)&&!pair.second.retiring){auto r=sharing.retire(pair.second.sharing,frame.tick);if(!r.accepted()){error=r.error;return false;}pair.second.retiring=true;}
        if(!frame.simulated){++flushed;return true;}++simulated;
        for(const auto& instance:frame.instances){
            if(instance.paused)continue;
            auto found=entries.find(instance.serial);
            if(found==entries.end()){
                f::LocalSpec spec;spec.owner="effects";spec.source=instance.serial;spec.finePerWorld=1;spec.originFine={static_cast<int>(std::floor(instance.origin.x-1)),static_cast<int>(std::floor(instance.origin.y-1)),static_cast<int>(std::floor(instance.origin.z-1))};spec.dimensions={8,8,8};spec.channels={{0,f::ProjectionReduction::VolumeAverage}};
                Entry entry;if(!local.create(spec,entry.local,error))return false;auto created=sharing.create({"effects",instance.serial},frame.tick);if(!created.result.accepted()){local.retire(entry.local,error);error=created.result.error;return false;}entry.sharing=created.handle;found=entries.emplace(instance.serial,entry).first;
            }
            auto& entry=found->second;if(!local.begin(entry.local,frame.commands,frame.fence,frame.tick,error))return false;
            for(std::size_t emitter=0;emitter<instance.emitters.size();++emitter)for(const auto& module:instance.asset->emitters[emitter].modules)if(module.kind==e::ModuleKind::FieldDeposit){require(module.fieldChannel=="density","Fixture writer received an unsupported field mapping");if(!local.splat(entry.local,0,*instance.emitters[emitter],module.fieldQuantum,frame.commands,frame.fence,error))return false;}
            if(!local.resolve(entry.local,frame.commands,frame.fence,error))return false;auto projection=local.project(entry.local,frame.tick,frame.commands,frame.fence,error);if(!projection)return false;
            const auto result=sharing.inspect(entry.sharing).state==f::LocalState::LocalOnly?sharing.promote(entry.sharing,projection,frame.tick):sharing.project(entry.sharing,projection,frame.tick);if(!result.accepted()){error=result.error;return false;}
        }
        if(!world.commit(frame.commands,frame.fence,frame.tick,error))return false;
        for(auto it=entries.begin();it!=entries.end();){auto r=sharing.settle(it->second.sharing);if(!r.accepted()){error=r.error;return false;}if(it->second.retiring){if(!it->second.localRetired&&!local.retire(it->second.local,error))return false;it=entries.erase(it);}else ++it;}
        return true;
    }
    void close(){std::string error;world.collect();local.collect();require(entries.empty()&&world.shutdown(error)&&local.shutdown(error),error.c_str());}
};
e::Handle spawn(e::GpuRuntime& runtime,const std::string& id){auto result=runtime.spawn(id);require(result.status==e::SpawnStatus::Accepted,result.reason.c_str());return result.handle;}
void step(Rig& rig,e::GpuRuntime& runtime){rig.begin();std::string error;require(runtime.step(rig.commands.p,rig.ticket(),rig.submitted,error),error.c_str());rig.submit();runtime.collect(rig.submitted);}
std::shared_ptr<f::GpuVisualView> view(Writer& writer,f::GpuLease reader){std::string error;auto result=writer.world.view(reader,error);require(!!result,error.c_str());return result;}
void cleanup(Rig& rig,e::GpuRuntime& runtime,Writer& writer,f::GpuLease reader){std::string error;runtime.clear();rig.begin();require(runtime.flush(rig.commands.p,rig.ticket(),rig.submitted,error)&&runtime.step(rig.commands.p,rig.ticket(),rig.submitted,error),error.c_str());rig.submit();runtime.collect(rig.submitted);require(runtime.shutdown(rig.submitted,error)&&writer.world.release(reader,error),error.c_str());writer.close();}
void authenticatedContracts(Rig& rig,const std::string& file){
    auto asset=e::loadCooked(file);require(asset->fieldChannels==std::vector<std::string>{"density"}&&asset->emitters.size()==2&&asset->emitters[0].modules[1].kind==e::ModuleKind::FieldDeposit&&asset->emitters[0].modules[1].fieldQuantum==100,"Native cook lost typed deposit quantum");e::GpuRuntime runtime(rig.device.p);runtime.install(asset);require(runtime.spawn(asset->id).status==e::SpawnStatus::UnsupportedFeature,"Unconfigured GPU runtime silently ignored field writes");e::Runtime cpu;cpu.install(asset);require(cpu.spawn(asset->id).status==e::SpawnStatus::UnsupportedFeature,"CPU fallback silently ignored field writes");require(!e::GpuParticlePool::unsupported(asset->emitters[0]).empty(),"Standalone GPU pool silently ignored field writes");
    std::ifstream input(file);const std::string bytes((std::istreambuf_iterator<char>(input)),{});auto container=nlohmann::json::parse(bytes);auto payload=nlohmann::json::parse(container.at("payloadJson").get<std::string>());payload["source"]["emitters"][0]["modules"][1]["params"]["quantum"]=UINT32_MAX;container["payloadJson"]=payload.dump();container["hash"]=e::sha256(container.at("payloadJson").get<std::string>());throws([&]{e::parseCooked(container.dump());},"Authenticated native reader accepted an overflowing authored deposit bound");payload=nlohmann::json::parse(nlohmann::json::parse(bytes).at("payloadJson").get<std::string>());payload["source"]["emitters"][0]["modules"].push_back({{"id","late"},{"type","acceleration"},{"after",{"deposit"}},{"params",{{"value",{0,1,0}}}}});container["payloadJson"]=payload.dump();container["hash"]=e::sha256(container.at("payloadJson").get<std::string>());throws([&]{e::parseCooked(container.dump());},"Native parser ignored an invalid dependency on the later deposit phase");std::string error;require(runtime.shutdown(rig.submitted,error),error.c_str());++groups;
}
void runtimeToFields(Rig& rig,Query& query,const std::shared_ptr<const e::Asset>& asset){
    Writer writer(rig);auto reader=read(writer.world);e::GpuRuntime runtime(rig.device.p,{32,4,32,16*1024*1024},[&](const e::GpuDepositFrame& frame,std::string& error){return writer.record(frame,error);});runtime.install(asset);auto a=spawn(runtime,asset->id),b=spawn(runtime,asset->id);step(rig,runtime);auto original=view(writer,reader);auto answer=query.run(rig,original,{{0,0,0,0}},0);require(answer[0].value==500&&answer[0].sourceLow==0&&runtime.stats().visual.alive==6,"Runtime deposits did not consume GPU-accepted spawns from both emitters/instances");
    require(runtime.pause(a,true),"Deposit pause rejected");step(rig,runtime);auto paused=view(writer,reader);answer=query.run(rig,paused,{{0,0,0,0}},1);require(answer[0].value==500&&answer[0].sourceLow==0&&writer.entries.size()==2,"Paused source disappeared or had its timestamp refreshed");require(runtime.move(b,{1,0,0}),"Local particle move rejected");step(rig,runtime);auto moved=view(writer,reader);answer=query.run(rig,moved,{{0,0,0,0},{1,0,0,0}},2);require(answer[0].value==250&&answer[1].value==250&&answer[0].ageLow==2,"Deposit local-space position or replace-not-add semantics incorrect");require(query.run(rig,original,{{0,0,0,0}},0)[0].value==500,"Later runtime ticks mutated an old field view");
    require(runtime.stop(a,true)&&!runtime.valid(a),"Deposit immediate stop did not invalidate its generation");rig.begin();std::string error;require(runtime.flush(rig.commands.p,rig.ticket(),rig.submitted,error)&&runtime.flush(rig.commands.p,rig.ticket(),rig.submitted,error),error.c_str());rig.submit();runtime.collect(rig.submitted);require(writer.flushed==2&&writer.entries.size()==2,"Flush did not synchronize the complete live set without re-splatting");step(rig,runtime);auto stopped=view(writer,reader);answer=query.run(rig,stopped,{{0,0,0,0},{1,0,0,0}},3);require(answer[0].value==0&&answer[1].value==250&&writer.entries.size()==1,"Stopped instance retained ghost density");require(runtime.stats().fieldDepositCalls==4&&runtime.stats().fieldDepositFlushCalls==2&&!runtime.stats().fieldDepositFailed,"Runtime deposit telemetry mismatch");
    evidence.push_back({{"case","authenticated-runtime-to-lef-wf"},{"initialDensity",500},{"densityAfterStop",250},{"pausedSourceAge",2},{"directGpuPools",true}});original.reset();paused.reset();moved.reset();stopped.reset();cleanup(rig,runtime,writer,reader);++groups;
}
void naturalDrain(Rig& rig,Query& query,const std::shared_ptr<const e::Asset>& original){
    auto asset=std::make_shared<e::Asset>(*original);asset->id="short_deposit";asset->hash="short";asset->duration=1;for(auto& e:asset->emitters)e.lifeMin=e.lifeMax=1;Writer writer(rig);auto reader=read(writer.world);e::GpuRuntime runtime(rig.device.p,{8,1,8,8*1024*1024},[&](const e::GpuDepositFrame& frame,std::string& error){return writer.record(frame,error);});runtime.install(asset);auto h=spawn(runtime,asset->id);step(rig,runtime);step(rig,runtime);require(!runtime.valid(h)&&runtime.stats().visual.alive==0,"Visual natural drain did not retire the effect");step(rig,runtime);auto empty=view(writer,reader);require(query.run(rig,empty,{{0,0,0,0}},2)[0].status==static_cast<unsigned>(f::Status::Unavailable)&&writer.entries.empty()&&writer.liveSets.back()==0,"Natural retirement was omitted from the complete live set");empty.reset();cleanup(rig,runtime,writer,reader);++groups;
}
void actualFence(Rig& rig,Query& query,const std::shared_ptr<const e::Asset>& asset){
    Writer writer(rig);auto reader=read(writer.world);e::GpuRuntime runtime(rig.device.p,{8,1,8,8*1024*1024},[&](const e::GpuDepositFrame& frame,std::string& error){return writer.record(frame,error);});runtime.install(asset);auto h=spawn(runtime,asset->id);gpu_test::Com<ID3D12Fence> gate;gpu_test::hr(rig.device.p->CreateFence(0,D3D12_FENCE_FLAG_NONE,IID_PPV_ARGS(gate.out())),"Create deposit gate");gpu_test::hr(rig.queue.p->Wait(gate.p,1),"Gate deposit queue");rig.begin();std::string error;const bool recorded=runtime.step(rig.commands.p,rig.ticket(),rig.submitted,error);rig.submit(false);auto retained=view(writer,reader);auto& entry=writer.entries.begin()->second;const bool privateRetired=writer.local.retire(entry.local,error);entry.localRetired=privateRetired;const bool withdrawalStaged=writer.sharing.retire(entry.sharing,1).accepted();entry.retiring=withdrawalStaged;const bool protectedResources=privateRetired&&withdrawalStaged&&writer.local.stats().retiredInstances==1&&!runtime.shutdown(rig.fence.p->GetCompletedValue(),error)&&!writer.local.shutdown(error)&&!writer.world.shutdown(error);gpu_test::hr(gate.p->Signal(1),"Release deposit gate");rig.wait();require(recorded&&protectedResources,"Runtime/LEF/WF released borrowed resources before their actual fence");runtime.collect(rig.submitted);require(query.run(rig,retained,{{0,0,0,0}},0)[0].value==250&&runtime.stop(h,true),"Gated deposit did not produce its exact contribution");retained.reset();cleanup(rig,runtime,writer,reader);evidence.push_back({{"case","deposits-actual-fence"},{"privateRetiredWhileBlocked",true},{"publishedViewSurvived",true}});++groups;
}
void failedDrivers(Rig& rig,const std::shared_ptr<const e::Asset>& asset){
    for(bool exception:{false,true}){unsigned calls=0;e::GpuRuntime runtime(rig.device.p,{8,1,8,8*1024*1024},[&](const e::GpuDepositFrame& frame,std::string& error){++calls;require(frame.simulated&&frame.instances.size()==1,"Failed driver did not receive its complete input");if(exception)throw std::runtime_error("injected recorder error");error="injected rejection";return false;});runtime.install(asset);spawn(runtime,asset->id);rig.begin();std::string error;require(!runtime.step(rig.commands.p,rig.ticket(),rig.submitted,error)&&!error.empty()&&runtime.stats().fieldDepositFailed&&runtime.stats().tick==0,"Driver rejection/exception advanced the runtime or disappeared");require(!runtime.step(rig.commands.p,rig.ticket(),rig.submitted,error)&&!runtime.flush(rig.commands.p,rig.ticket(),rig.submitted,error)&&!runtime.prepareDraw(rig.commands.p,rig.ticket(),error)&&calls==1,"Failed recording was retried and could double-simulate particles");rig.submit();require(runtime.spawn(asset->id).status==e::SpawnStatus::UnsupportedFeature&&runtime.shutdown(rig.submitted,error),error.c_str());}++groups;
}
