int main(int argc,char** argv){try{std::string adapter="AMD",fixture="build/effects-deposits/fixture.cooked.json";for(int i=1;i<argc;++i){const std::string key=argv[i];if((key=="--adapter"||key=="--fixture")&&i+1<argc){auto value=std::string(argv[++i]);if(key=="--adapter")adapter=value;else fixture=value;}else throw std::runtime_error("Usage: native_effect_deposits_tests [--adapter substring] [--fixture file]");}Rig rig(adapter);require(rig.debug,"Deposit D3D12 debug layer unavailable");Query query(rig);authenticatedContracts(rig,fixture);auto asset=e::loadCooked(fixture);runtimeToFields(rig,query,asset);naturalDrain(rig,query,asset);actualFence(rig,query,asset);failedDrivers(rig,asset);const auto errors=rig.debugErrors();require(!errors,"Field deposit D3D12 debug errors");std::cout<<nlohmann::json{{"schema","nativegpu.effect-field-deposits-evidence/1"},{"ok",true},{"groups",groups},{"checks",checks},{"adapter",rig.adapter},{"debugLayer",rig.debug},{"debugErrors",errors},{"cases",evidence},{"fieldValueReadback",false},{"particleAttributeReadback",false},{"boundedRuntimeTelemetry",true},{"rendererIntegrated",false}}.dump()<<'\n';}catch(const std::exception& error){std::cerr<<"Effect deposits failed after "<<checks<<" checks: "<<error.what()<<'\n';return 1;}}
